-- Starter posts for the official @snapspoon account, so the feed isn't empty on launch day.
-- Run this once in the Supabase SQL Editor AFTER the @snapspoon account exists (launch guide, Step 5).
-- The photos are hosted on the website (docs/recipes). Running it again just updates the same posts.

insert into public.shared_recipes (id, owner, recipe, created_at)
select v.id, p.id, v.recipe, v.created_at
from public.profiles p, (values
  ('snapspoon-r1', '{"id":"snapspoon-r1","title":"Greek yogurt berry bowl","cat":"Breakfast","min":5,"serv":1,"kcal":310,"p":24,"c":38,"f":7,"tags":["High protein","Vegetarian","Under 400"],"ing":["200 g 0% Greek yogurt","80 g mixed berries","15 g granola","1 tsp honey","1 tbsp chia seeds"],"steps":["Spoon yogurt into a bowl.","Top with berries, granola and chia.","Drizzle with honey and serve."],"caption":"Greek yogurt berry bowl: 310 kcal and 24 g protein, ready in 5 minutes. Save it for later. #healthyrecipes #breakfast #highprotein #vegetarian","image":"https://avivloya.github.io/BiteBoard/recipes/r1.jpg"}'::jsonb, now() - interval '96 hours'),
  ('snapspoon-r2', '{"id":"snapspoon-r2","title":"Chicken burrito bowl","cat":"Lunch","min":25,"serv":2,"kcal":520,"p":42,"c":55,"f":13,"tags":["High protein","Meal prep"],"ing":["300 g chicken breast","120 g cooked brown rice","1 can black beans, rinsed","1 cup corn","Salsa, lime, coriander","½ avocado"],"steps":["Season chicken with cumin, paprika, salt; grill 6 min per side.","Warm beans and corn.","Slice chicken and build bowls over rice.","Top with salsa, avocado, lime and coriander."],"caption":"Chicken burrito bowl: 520 kcal and 42 g protein, ready in 25 minutes. Save it for later. #healthyrecipes #lunch #highprotein #mealprep","image":"https://avivloya.github.io/BiteBoard/recipes/r2.jpg"}'::jsonb, now() - interval '90 hours'),
  ('snapspoon-r3', '{"id":"snapspoon-r3","title":"Zucchini noodle pad thai","cat":"Dinner","min":20,"serv":2,"kcal":380,"p":26,"c":24,"f":20,"tags":["Low carb","Under 400"],"ing":["3 zucchini, spiralized","200 g shrimp","1 egg","2 tbsp peanut butter","1 tbsp soy sauce","1 tbsp lime juice","Bean sprouts, scallions"],"steps":["Whisk peanut butter, soy, lime and a splash of water.","Sear shrimp 2 min a side; push aside and scramble the egg.","Add zoodles and sauce; toss 2 min.","Top with sprouts and scallions."],"caption":"Zucchini noodle pad thai: 380 kcal and 26 g protein, ready in 20 minutes. Save it for later. #healthyrecipes #dinner #lowcarb #under400","image":"https://avivloya.github.io/BiteBoard/recipes/r3.jpg"}'::jsonb, now() - interval '84 hours'),
  ('snapspoon-r4', '{"id":"snapspoon-r4","title":"Overnight protein oats","cat":"Breakfast","min":5,"serv":1,"kcal":390,"p":30,"c":48,"f":9,"tags":["High protein","Meal prep","Vegetarian","Under 400"],"ing":["50 g rolled oats","1 scoop vanilla protein","150 ml almond milk","½ banana, sliced","1 tsp cinnamon"],"steps":["Stir oats, protein, milk and cinnamon in a jar.","Refrigerate overnight.","Top with banana before eating."],"caption":"Overnight protein oats: 390 kcal and 30 g protein, ready in 5 minutes. Save it for later. #healthyrecipes #breakfast #highprotein #mealprep","image":"https://avivloya.github.io/BiteBoard/recipes/r4.jpg"}'::jsonb, now() - interval '78 hours'),
  ('snapspoon-r5', '{"id":"snapspoon-r5","title":"Salmon, greens & quinoa","cat":"Dinner","min":25,"serv":2,"kcal":540,"p":38,"c":36,"f":26,"tags":["High protein","Omega-3"],"ing":["2 salmon fillets (130 g each)","100 g dry quinoa","2 cups spinach","1 cup broccoli","Lemon, garlic, olive oil"],"steps":["Cook quinoa in 200 ml water, 12 min.","Roast salmon and broccoli at 200°C for 12 min.","Wilt spinach with garlic.","Plate with lemon."],"caption":"Salmon, greens & quinoa: 540 kcal and 38 g protein, ready in 25 minutes. Save it for later. #healthyrecipes #dinner #highprotein #omega3","image":"https://avivloya.github.io/BiteBoard/recipes/r5.jpg"}'::jsonb, now() - interval '72 hours'),
  ('snapspoon-r6', '{"id":"snapspoon-r6","title":"Turkey lettuce wraps","cat":"Lunch","min":15,"serv":2,"kcal":290,"p":30,"c":10,"f":14,"tags":["Low carb","High protein","Under 400"],"ing":["300 g lean ground turkey","1 head butter lettuce","1 carrot, grated","2 tbsp hoisin","1 tsp sesame oil","Ginger, garlic"],"steps":["Brown turkey with ginger and garlic.","Stir in hoisin and sesame oil.","Spoon into lettuce cups and top with carrot."],"caption":"Turkey lettuce wraps: 290 kcal and 30 g protein, ready in 15 minutes. Save it for later. #healthyrecipes #lunch #lowcarb #highprotein","image":"https://avivloya.github.io/BiteBoard/recipes/r6.jpg"}'::jsonb, now() - interval '66 hours'),
  ('snapspoon-r7', '{"id":"snapspoon-r7","title":"Lentil & spinach soup","cat":"Dinner","min":35,"serv":4,"kcal":280,"p":17,"c":42,"f":4,"tags":["Vegan","Vegetarian","Meal prep","Under 400"],"ing":["250 g red lentils","1 onion, 2 carrots, 2 celery","1 can chopped tomatoes","1 L vegetable stock","2 cups spinach","Cumin, smoked paprika"],"steps":["Soften the vegetables 6 min.","Add spices, lentils, tomatoes and stock.","Simmer 20 min, stir in spinach."],"caption":"Lentil & spinach soup: 280 kcal and 17 g protein, ready in 35 minutes. Save it for later. #healthyrecipes #dinner #vegan #vegetarian","image":"https://avivloya.github.io/BiteBoard/recipes/r7.jpg"}'::jsonb, now() - interval '60 hours'),
  ('snapspoon-r8', '{"id":"snapspoon-r8","title":"Cottage cheese pancakes","cat":"Breakfast","min":15,"serv":2,"kcal":330,"p":25,"c":30,"f":11,"tags":["High protein","Vegetarian","Under 400"],"ing":["200 g cottage cheese","2 eggs","60 g oat flour","1 tsp baking powder","Berries to serve"],"steps":["Blend everything except berries until smooth.","Cook small pancakes 2 min per side.","Serve with berries."],"caption":"Cottage cheese pancakes: 330 kcal and 25 g protein, ready in 15 minutes. Save it for later. #healthyrecipes #breakfast #highprotein #vegetarian","image":"https://avivloya.github.io/BiteBoard/recipes/r8.jpg"}'::jsonb, now() - interval '54 hours'),
  ('snapspoon-r9', '{"id":"snapspoon-r9","title":"Sheet-pan chicken fajitas","cat":"Dinner","min":30,"serv":3,"kcal":450,"p":40,"c":38,"f":14,"tags":["High protein","Meal prep"],"ing":["450 g chicken breast, sliced","3 bell peppers","1 red onion","Fajita spice, olive oil","6 small corn tortillas","Greek yogurt as sour cream"],"steps":["Toss chicken and veg with spice and oil.","Roast at 220°C for 20 min.","Serve in warm tortillas with yogurt."],"caption":"Sheet-pan chicken fajitas: 450 kcal and 40 g protein, ready in 30 minutes. Save it for later. #healthyrecipes #dinner #highprotein #mealprep","image":"https://avivloya.github.io/BiteBoard/recipes/r9.jpg"}'::jsonb, now() - interval '48 hours'),
  ('snapspoon-r10', '{"id":"snapspoon-r10","title":"Tuna white bean salad","cat":"Lunch","min":10,"serv":2,"kcal":360,"p":32,"c":28,"f":12,"tags":["High protein","No cook","Under 400"],"ing":["2 cans tuna in water","1 can cannellini beans","½ red onion","Cherry tomatoes, cucumber","Lemon, olive oil, parsley"],"steps":["Drain tuna and beans.","Chop vegetables and herbs.","Toss with lemon and 1 tbsp olive oil."],"caption":"Tuna white bean salad: 360 kcal and 32 g protein, ready in 10 minutes. Save it for later. #healthyrecipes #lunch #highprotein #nocook","image":"https://avivloya.github.io/BiteBoard/recipes/r10.jpg"}'::jsonb, now() - interval '42 hours'),
  ('snapspoon-r11', '{"id":"snapspoon-r11","title":"Tofu veggie stir-fry","cat":"Dinner","min":20,"serv":2,"kcal":410,"p":24,"c":40,"f":16,"tags":["Vegan","Vegetarian"],"ing":["300 g firm tofu","Broccoli, snap peas, pepper","2 tbsp soy sauce","1 tbsp rice vinegar","Garlic, ginger, chili","120 g cooked jasmine rice"],"steps":["Press and cube tofu; crisp in a hot pan.","Stir-fry vegetables 4 min.","Add sauce and tofu, toss, serve over rice."],"caption":"Tofu veggie stir-fry: 410 kcal and 24 g protein, ready in 20 minutes. Save it for later. #healthyrecipes #dinner #vegan #vegetarian","image":"https://avivloya.github.io/BiteBoard/recipes/r11.jpg"}'::jsonb, now() - interval '36 hours'),
  ('snapspoon-r12', '{"id":"snapspoon-r12","title":"Chocolate protein mug cake","cat":"Snack","min":3,"serv":1,"kcal":210,"p":22,"c":16,"f":6,"tags":["High protein","Under 400","Vegetarian"],"ing":["1 scoop chocolate protein","1 tbsp cocoa","1 egg white","3 tbsp milk","¼ tsp baking powder"],"steps":["Mix everything in a mug.","Microwave 60–75 seconds.","Let cool 1 minute."],"caption":"Chocolate protein mug cake: 210 kcal and 22 g protein, ready in 3 minutes. Save it for later. #healthyrecipes #snack #highprotein #under400","image":"https://avivloya.github.io/BiteBoard/recipes/r12.jpg"}'::jsonb, now() - interval '30 hours'),
  ('snapspoon-r13', '{"id":"snapspoon-r13","title":"Shakshuka for two","cat":"Breakfast","min":20,"serv":2,"kcal":300,"p":18,"c":20,"f":16,"tags":["Vegetarian","Low carb","Under 400"],"ing":["4 eggs","1 can crushed tomatoes","1 red pepper, 1 onion","Cumin, paprika, chili","Feta and parsley"],"steps":["Soften pepper and onion with spices.","Add tomatoes, simmer 8 min.","Crack in eggs, cover until set.","Top with feta and parsley."],"caption":"Shakshuka for two: 300 kcal and 18 g protein, ready in 20 minutes. Save it for later. #healthyrecipes #breakfast #vegetarian #lowcarb","image":"https://avivloya.github.io/BiteBoard/recipes/r13.jpg"}'::jsonb, now() - interval '24 hours'),
  ('snapspoon-r14', '{"id":"snapspoon-r14","title":"Hummus veggie snack box","cat":"Snack","min":5,"serv":1,"kcal":240,"p":9,"c":26,"f":11,"tags":["Vegan","No cook","Under 400"],"ing":["60 g hummus","Carrot & cucumber sticks","6 cherry tomatoes","1 small wholewheat pita"],"steps":["Pack hummus in a small pot.","Arrange vegetables and pita around it."],"caption":"Hummus veggie snack box: 240 kcal and 9 g protein, ready in 5 minutes. Save it for later. #healthyrecipes #snack #vegan #nocook","image":"https://avivloya.github.io/BiteBoard/recipes/r14.jpg"}'::jsonb, now() - interval '18 hours'),
  ('snapspoon-r15', '{"id":"snapspoon-r15","title":"Beef & broccoli rice bowl","cat":"Dinner","min":25,"serv":2,"kcal":560,"p":40,"c":52,"f":18,"tags":["High protein"],"ing":["300 g flank steak, thin sliced","3 cups broccoli","2 tbsp low-sodium soy","1 tbsp honey","Garlic, ginger, cornstarch","150 g cooked rice"],"steps":["Toss beef in cornstarch; sear in batches.","Steam broccoli 3 min.","Simmer sauce, add beef and broccoli.","Serve over rice."],"caption":"Beef & broccoli rice bowl: 560 kcal and 40 g protein, ready in 25 minutes. Save it for later. #healthyrecipes #dinner #highprotein","image":"https://avivloya.github.io/BiteBoard/recipes/r15.jpg"}'::jsonb, now() - interval '12 hours'),
  ('snapspoon-r16', '{"id":"snapspoon-r16","title":"Mango chili chia pudding","cat":"Snack","min":5,"serv":2,"kcal":230,"p":7,"c":30,"f":10,"tags":["Vegan","Meal prep","Under 400"],"ing":["4 tbsp chia seeds","300 ml light coconut milk","1 mango, diced","Pinch of chili and lime zest"],"steps":["Stir chia into coconut milk; chill 3 hours.","Top with mango, chili and lime zest."],"caption":"Mango chili chia pudding: 230 kcal and 7 g protein, ready in 5 minutes. Save it for later. #healthyrecipes #snack #vegan #mealprep","image":"https://avivloya.github.io/BiteBoard/recipes/r16.jpg"}'::jsonb, now() - interval '6 hours')
) as v(id, recipe, created_at)
where lower(p.handle) = 'snapspoon'
on conflict (id) do update set recipe = excluded.recipe;
